using System;using System.Collections.Generic;using RimWorld;using Verse;using Verse.AI;
namespace ElementalHearts {
 public static class SovereignCyclone {
  public const string JobName="EH_SovereignCyclone";
  public static bool Busy(Pawn p){return p!=null&&p.CurJobDef!=null&&p.CurJobDef.defName==JobName;}
  public static bool Impacting(Pawn p){var d=p==null||p.jobs==null?null:p.jobs.curDriver as JobDriver_SovereignCyclone;return d!=null&&d.impacting;}
  public static List<Pawn> Targets(Pawn source){var result=new List<Pawn>();if(source==null||!source.Spawned)return result;var seen=new HashSet<int>();int scanned=0;foreach(var cell in GenRadial.RadialCellsAround(source.Position,4f,true)){if(!cell.InBounds(source.Map)||ElementalCombatPolicy.Controlled(source)&&cell.Fogged(source.Map)||!LightningCombat.ClearLine(source.Position,cell,source.Map))continue;foreach(var thing in cell.GetThingList(source.Map)){if(++scanned>CycloneControlRules.SearchThings)return result;var p=thing as Pawn;if(!WindCombat.Eligible(source,p)||!seen.Add(p.thingIDNumber))continue;result.Add(p);if(result.Count>=CycloneControlRules.CandidateLimit)return result;}}return result;}
  public static int Crowd(Pawn p){int n=0;foreach(var target in Targets(p))if(target.HostileTo(p)&&!target.IsPrisoner&&!target.IsSlave&&++n>=2)break;return n;}
 }
 public sealed class HediffCompProperties_SovereignCyclone:HediffCompProperties {public HediffCompProperties_SovereignCyclone(){compClass=typeof(HediffComp_SovereignCyclone);}}
 public sealed class HediffComp_SovereignCyclone:HediffComp {
  public int readyAt;
  public static HediffComp_SovereignCyclone On(Pawn p){if(p==null||p.health==null)return null;foreach(var h in p.health.hediffSet.hediffs){var c=h.TryGetComp<HediffComp_SovereignCyclone>();if(c!=null)return c;}return null;}
  public bool CanAct{get{var c=HediffComp_WindAbilities.On(Pawn);return CycloneEvolution.Active(Pawn)&&c!=null&&c.CanAct&&!c.Busy&&!AzureEvolution.Evolving(Pawn)&&HediffComp_ElementalTransform.Active(Pawn);}}
  public override void CompExposeData(){Scribe_Values.Look(ref readyAt,"EH_sovereignCycloneReadyAt");}
  public bool TryCast(){int now=Find.TickManager.TicksGame;if(!CanAct||!CycloneControlRules.Trigger(SovereignCyclone.Crowd(Pawn),now>=readyAt))return false;var job=JobMaker.MakeJob(DefDatabase<JobDef>.GetNamed(SovereignCyclone.JobName),Pawn);Pawn.jobs.StartJob(job,JobCondition.InterruptForced,resumeCurJobAfterwards:true,cancelBusyStances:true);if(Pawn.CurJob!=job)return false;readyAt=now+CycloneControlRules.Cooldown;return true;}
  public override IEnumerable<Gizmo> CompGetGizmos(){if(!ElementalCombatPolicy.Controlled(Pawn)||!Pawn.Drafted)yield break;var c=new Command_Action{defaultLabel="Sovereign Cyclone",defaultDesc="Automatically answers at least two visible hostiles within four cells. A 0.4-second wind sigil forms, then at most six eligible pawns are held aloft for two seconds. Release delivers one committed strike per victim and pushes survivors up to three clear, unoccupied cells outward. No damage during the hold, collision damage or building/terrain changes. Forty-second cooldown; no resource cost. Shared Auto Combat/Non-lethal controls apply. New orders, undrafting, incapacitation, death or loss of the caster release owned captures safely. Can also be pressed under the same crowd condition.",icon=CycloneVfx.Icon(4),groupable=false,action=()=>TryCast()};if(!CanAct)c.Disable("Transform, equip a melee weapon and finish the current action first.");else if(Find.TickManager.TicksGame<readyAt)c.Disable("Recharging: "+Math.Ceiling((readyAt-Find.TickManager.TicksGame)/60f)+"s");else if(SovereignCyclone.Crowd(Pawn)<2)c.Disable("Requires at least two nearby visible hostiles.");yield return c;}
 }
 public sealed class JobDriver_SovereignCyclone:JobDriver {
  public int elapsed;bool captured,released;public bool impacting;List<Pawn> targets=new List<Pawn>();HashSet<int> struck=new HashSet<int>();int effect;IntVec3 center=IntVec3.Invalid;
  const int ReleaseAt=CycloneControlRules.FormationTicks+CycloneControlRules.HoldTicks,EndAt=ReleaseAt+24;
  public override bool TryMakePreToilReservations(bool errorOnFailed){return true;}
  bool Valid(){var wind=HediffComp_WindAbilities.On(pawn);return pawn.CurJob==job&&(!center.IsValid||pawn.Position==center)&&CycloneEvolution.Active(pawn)&&ElementalTeaching.Ready(pawn)&&wind!=null&&wind.HasWeapon&&(!ElementalCombatPolicy.Controlled(pawn)||pawn.Drafted)&&HediffComp_ElementalTransform.Active(pawn)&&!HediffComp_ElementalTransform.Transforming(pawn)&&!ElementalAnimationBridge.ExternallyControlled(pawn);}
  public override void ExposeData(){base.ExposeData();if(Scribe.mode==LoadSaveMode.Saving)targets.RemoveAll(p=>p==null||p.Destroyed||!p.Spawned||p.Map!=pawn.Map);Scribe_Values.Look(ref center,"EH_sovereignCenter",IntVec3.Invalid);Scribe_Values.Look(ref elapsed,"EH_sovereignElapsed");Scribe_Values.Look(ref captured,"EH_sovereignCaptured");Scribe_Values.Look(ref released,"EH_sovereignReleased");Scribe_Collections.Look(ref targets,"EH_sovereignTargets",LookMode.Reference);Scribe_Collections.Look(ref struck,"EH_sovereignStruck",LookMode.Value);if(targets==null)targets=new List<Pawn>();if(struck==null)struck=new HashSet<int>();}
  void StopEffect(){if(effect!=0&&pawn.Spawned)pawn.Map.GetComponent<MapComponent_CycloneVfx>().Stop(effect);effect=0;}
  void Visual(){StopEffect();if(!pawn.Spawned)return;if(elapsed<CycloneControlRules.FormationTicks)effect=CycloneVfx.Emit(pawn,CycloneEffect.Formation,pawn.DrawPos,pawn.DrawPos,CycloneControlRules.FormationTicks,7,null,elapsed);else if(elapsed<ReleaseAt)effect=CycloneVfx.Emit(pawn,CycloneEffect.Loop,pawn.DrawPos,pawn.DrawPos,CycloneControlRules.HoldTicks,8,null,elapsed-CycloneControlRules.FormationTicks);else effect=CycloneVfx.Emit(pawn,CycloneEffect.Release,pawn.DrawPos,pawn.DrawPos,24,9,null,elapsed-ReleaseAt);}
  void Capture(){if(captured)return;captured=true;foreach(var target in SovereignCyclone.Targets(pawn)){if(targets.Count>=CycloneControlRules.MaxVictims)break;if(CycloneAirbound.Apply(pawn,target,Math.Max(1,ReleaseAt-elapsed),job.loadID))targets.Add(target);}Visual();ElementalAudio.Ability(pawn,ElementalSound.Spin);}
  void Release(){if(released)return;released=true;impacting=true;ElementalAudio.Ability(pawn,ElementalSound.Burst);try{foreach(var target in targets){var hold=CycloneAirbound.On(target);if(hold==null||!hold.Owned(pawn,job.loadID))continue;try{if(WindCombat.Eligible(pawn,target)&&pawn.Position.DistanceToSquared(target.Position)<=25&&LightningCombat.ClearLine(pawn.Position,target.Position,pawn.Map)&&struck.Add(target.thingIDNumber))WindCombat.Strike(pawn,target,3f);}finally{hold.Release(true);}}}finally{impacting=false;}Visual();}
  void Cleanup(){impacting=false;StopEffect();foreach(var target in targets){var c=CycloneAirbound.On(target);if(c!=null&&c.Owned(pawn,job.loadID)&&c.Controlling)c.Cancel();}var wind=HediffComp_WindAbilities.On(pawn);if(wind!=null)wind.nextAutoCheck=Find.TickManager.TicksGame+12;}
  protected override IEnumerable<Toil> MakeNewToils(){AddFinishAction(condition=>Cleanup());this.FailOn(()=>!Valid());var cast=new Toil();cast.defaultCompleteMode=ToilCompleteMode.Never;cast.handlingFacing=true;cast.initAction=()=>{if(!center.IsValid)center=pawn.Position;pawn.pather.StopDead();pawn.stances.CancelBusyStanceHard();Visual();if(elapsed==0)ElementalAudio.Ability(pawn,ElementalSound.Charge);};cast.tickAction=()=>{pawn.pather.StopDead();elapsed++;if(elapsed>=CycloneControlRules.FormationTicks&&!captured)Capture();if(elapsed>=ReleaseAt&&!released)Release();if(elapsed>=EndAt)ReadyForNextToil();};yield return cast;}
 }
}
